import pandas as pd


def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    if events.empty:
        return {
            "user_sessions": pd.DataFrame(
                columns=[
                    "user_id",
                    "session_num",
                    "session_start",
                    "session_end",
                    "event_count",
                    "heartbeat_count",
                ]
            )
        }

    events["event_ts"] = pd.to_datetime(events["event_ts"])
    events = events.sort_values(by=["user_id", "event_ts", "event_id"], kind="mergesort")

    threshold = pd.Timedelta(minutes=30)

    results = []

    for user_id, grp in events.groupby("user_id", sort=False):
        session_open = False
        session_num = 0
        last_activity_ts = None
        session_start = None
        event_count = 0
        heartbeat_count = 0

        def close_session():
            nonlocal session_open, session_num, session_start
            nonlocal last_activity_ts, event_count, heartbeat_count
            results.append(
                {
                    "user_id": user_id,
                    "session_num": session_num,
                    "session_start": session_start,
                    "session_end": last_activity_ts,
                    "event_count": event_count,
                    "heartbeat_count": heartbeat_count,
                }
            )
            session_open = False

        for _, row in grp.iterrows():
            etype = row["event_type"]
            ts = row["event_ts"]

            if etype in ("view", "click", "logout"):
                if (not session_open) or (ts - last_activity_ts > threshold):
                    # start new session
                    if session_open:
                        close_session()
                    session_num += 1
                    session_start = ts
                    last_activity_ts = ts
                    event_count = 1
                    heartbeat_count = 0
                    session_open = True
                else:
                    event_count += 1
                    last_activity_ts = ts

                if etype == "logout":
                    close_session()
            elif etype == "heartbeat":
                if session_open and (ts - last_activity_ts <= threshold):
                    event_count += 1
                    heartbeat_count += 1
                # else dropped
            else:
                # unknown event type - ignore, treat as non-activity, non-heartbeat
                pass

        if session_open:
            close_session()

    out_cols = [
        "user_id",
        "session_num",
        "session_start",
        "session_end",
        "event_count",
        "heartbeat_count",
    ]

    if results:
        out_df = pd.DataFrame(results, columns=out_cols)
    else:
        out_df = pd.DataFrame(columns=out_cols)

    return {"user_sessions": out_df}
